    "A delivery is abandoned after {attempts} attempts." : "Od isporuke se odustaje posle {attempts} pokušaja.",
    "The longest-failing one was last tried {ago}." : "Ona koja najduže ne uspeva poslednji put je pokušana {ago}.",
